```yaml
name: Auto‑approve workflows

on:
  pull_request:
    types: [labeled, unlabeled, synchronize]
    branches:
      - main
      - release-**

jobs:
  approve:
    runs-on: ubuntu-latest
    if: |
      github.event.pull_request.head.repo.full_name == github.repository &&
      (github.event.pull_request.base.ref == 'main' ||
       startsWith(github.event.pull_request.base.ref, 'release-'))
    permissions:
      pull-requests: read
      contents: read
      actions: write
    steps:
      - name: Determine approval eligibility
        id: eligibility
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const okToTest = pr.labels.some(label => label.name === 'ok-to-test');
            const author = pr.user.login;
            const searchQuery = `repo:${context.repo.owner}/${context.repo.repo} type:pr author:${author} state:closed`;
            const searchResult = await github.rest.search.issuesAndPullRequests({
              q: searchQuery,
              per_page: 1
            });
            const total = searchResult.data.total_count;
            const isReturning = total > 1;
            const shouldApprove = okToTest || isReturning;
            const fs = require('fs');
            const outputPath = process.env.GITHUB_OUTPUT;
            fs.appendFileSync(outputPath, `ok_to_test=${okToTest}\n`);
            fs.appendFileSync(outputPath, `is_returning=${isReturning}\n`);
            fs.appendFileSync(outputPath, `should_approve=${shouldApprove}\n`);

      - name: Approve pending workflow runs
        if: steps.eligibility.outputs.should_approve == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const headBranch = pr.head.ref;
            const runs = await github.rest.actions.listWorkflowRuns({
              owner,
              repo,
              head_branch: headBranch,
              event: 'pull_request',
              status: 'pending',
              per_page: 100
            });
            for (const run of runs.data.workflow_runs) {
              await github.rest.actions.createWorkflowRunApproval({
                owner,
                repo,
                run_id: run.id
              });
              console.log(`Approved workflow run ${run.id}`);
            }
